INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('e9f1550f-44ab-4661-b362-0abdb4f33e74'::uuid, 'card_description', 'A dolmen with a 12-metre burial passage and an "oven door" entrance just 2 metres high and 1 metre wide. Three massive capstones cover the main 6-metre-long chamber.', 'Inside a large tumulus near Le Pouget, the Gallardet Dolmen hides a 12 metre long alley. Its entrance is likened to an oven door, and three large capstones cover its main chamber.', 'teaser-card-s026:e9f1550f-44ab-4661-b362-0abdb4f33e74:card_description', 'teaser-card-s026 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'dfbe6ca97d73e7293aa35c040c0d6dac1ae54739c848db3485bf554575415015|5f113ac1e6f549e5f40fc3f83ea9b67ff0fe9e4eb76a5fc5c30545b656dc7aec|5f113ac1e6f549e5f40fc3f83ea9b67ff0fe9e4eb76a5fc5c30545b656dc7aec', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Inside a large tumulus near Le Pouget, the Gallardet Dolmen hides a 12 metre long alley. Its entrance is likened to an oven door, and three large capstones cover its main chamber."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Gallardet Dolmen is a large tumulus [S2]; it is near Le Pouget [S1]; the tumulus contains a 12 metre long alley [S2]; its entrance is described as like an oven door [S4]; three large capstones cover its main chamber [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Gallardet Dolmen is a dolmen (megalithic tomb) near Le Pouget, France (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Gallardet_Dolmen]; It lies inside a large tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Gallardet_Dolmen]; The tumulus contains a 12 metre long alley [SUPPORTED: https://en.wikipedia.org/wiki/Gallardet_Dolmen]; Its entrance is likened to an oven door [SUPPORTED: https://en.wikipedia.org/wiki/Gallardet_Dolmen]; Three large capstones cover the main chamber [SUPPORTED: https://en.wikipedia.org/wiki/Gallardet_Dolmen]"}]'::jsonb),
    ('ea2fba59-c9e4-4471-bb38-b07cd2d3845a'::uuid, 'card_description', 'Oram''s Arbour was an enclosed settlement during the Iron Age, in what is now Winchester. Limited dating evidence suggests the enclosure was dug in the early-mid first century BC.', 'In what is now Winchester lay Oram''s Arbour, an Iron Age oppidum whose enclosure was perhaps dug in the early-mid first century BC. The Roman town wall later cut across its eastern end.', 'teaser-card-s026:ea2fba59-c9e4-4471-bb38-b07cd2d3845a:card_description', 'teaser-card-s026 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'af037cac0a86df8d58cbd3b5b016b6d5db98e79ad5c055d6607b6f2dd643d401|a09e2643dd816473c1425adeb3bdbf2b9f2a70865999a5888bc0fa9b294f48a8|a09e2643dd816473c1425adeb3bdbf2b9f2a70865999a5888bc0fa9b294f48a8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In what is now Winchester lay Oram''s Arbour, an Iron Age oppidum whose enclosure was perhaps dug in the early-mid first century BC. The Roman town wall later cut across its eastern end."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Oram''s Arbour lay in what is now Winchester [S1]; it was an Iron Age oppidum (enclosed settlement) [S1]; its enclosure was perhaps dug in the early-mid first century BC (hedged) [S2]; a Roman town wall, later than the settlement, cut across its eastern end [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Oram''s Arbour is an oppidum (enclosed settlement), the kind of place [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]; It lies in what is now Winchester, England [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]; It dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]; The enclosure was dug in the early-mid first century BC (hedged as ''perhaps'') [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]; The Roman town wall cut across its eastern end [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]; The Roman wall came later than the Iron Age settlement [SUPPORTED: https://en.wikipedia.org/wiki/Oram%27s_Arbour]"}]'::jsonb),
    ('eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133'::uuid, 'card_description', NULL, 'On the North York Moors lies Wade''s Causeway, a Roman road or possibly a Neolithic structure. For centuries folklore credited its building to Wade, a giant from Germanic mythology.', 'teaser-card-s026:eab8cd53-0fe7-4b42-a9cc-8b9ec68ae133:card_description', 'teaser-card-s026 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '97d3760f81c19c9af414897d745c5e8fb75d53ff98eeb7ea4d8d79a3cce74cd8|37759757594e854b209f8f8978239e15658bd251b63b56913ad5902335a44fb0|37759757594e854b209f8f8978239e15658bd251b63b56913ad5902335a44fb0', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the North York Moors lies Wade''s Causeway, a Roman road or possibly a Neolithic structure. For centuries folklore credited its building to Wade, a giant from Germanic mythology."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Wade''s Causeway lies on the North York Moors [S1]; it is a Roman road or possibly a Neolithic structure (hedged) [S1]; it has been the subject of folklore for centuries [S2]; its construction was attributed to Wade [S3]; Wade is a giant from Germanic mythology [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Wade''s Causeway is a Roman road (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]; It is possibly a Neolithic structure [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]; It lies on the North York Moors [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]; Folklore credited its building to Wade for centuries [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]; Its construction was attributed to Wade, a giant [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]; Wade is a figure from Germanic mythology [SUPPORTED: https://en.wikipedia.org/wiki/Wade%27s_Causeway]"}]'::jsonb),
    ('eb13e438-eba3-44d7-8189-9365e245f0b8'::uuid, 'card_description', 'The city was rebuilt during the early 700s CE, though less prominent and more sparsely populated than before.', 'A large fire destroyed much of Witzna, the Maya city of Bahlam Jol, matching a hieroglyphic account at Naranjo of a rebel vassal burned on 21 May 697 CE. It was rebuilt in the early 700s CE.', 'teaser-card-s026:eb13e438-eba3-44d7-8189-9365e245f0b8:card_description', 'teaser-card-s026 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'ecc643b9b25c2a8e7e098ca3ff7af9220316363bce7626fc878993f47c878e90|abb51289451f316db08e2f9abfb9252a95dda9cddba3867d14d74461087a194e|abb51289451f316db08e2f9abfb9252a95dda9cddba3867d14d74461087a194e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "A large fire destroyed much of Witzna, the Maya city of Bahlam Jol, matching a hieroglyphic account at Naranjo of a rebel vassal burned on 21 May 697 CE. It was rebuilt in the early 700s CE."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "a large fire destroyed much of Witzna [S6]; Witzna was a Maya city [S1]; the city was known as Bahlam Jol [S2]; the fire matches a hieroglyphic account at Naranjo [S6]; the account describes the burning of a rebellious vassal city [S6]; the burning is dated to 21 May 697 CE [S6]; the city was rebuilt in the early 700s CE [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Witzna is a Maya city (archaeological site) in Guatemala [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; Witzna was known to the ancient Maya as Bahlam Jol [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; A large fire destroyed much of the city [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; The fire matches a hieroglyphic account at Naranjo [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; The account describes a rebel vassal (Bahlam Jol) being burned [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; The burning is dated 21 May 697 CE [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]; The city was rebuilt in the early 700s CE [SUPPORTED: https://en.wikipedia.org/wiki/Witzna]"}]'::jsonb),
    ('ec0a83d5-737e-48de-a79c-d709ad794e60'::uuid, 'card_description', 'Thirty rock-cut Buddhist cave monuments from the 2nd century BC to 650 AD. The paintings inside are masterpieces that convey emotion through gesture and form alone.', 'Carved into a 75-metre wall of rock, the Ajanta Caves hold Buddhist monasteries and worship-halls; Caves 1, 2, 16 and 17 form the largest corpus of surviving ancient Indian wall-paintings.', 'teaser-card-s026:ec0a83d5-737e-48de-a79c-d709ad794e60:card_description', 'teaser-card-s026 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '024584a4a2ccc473003b9a5eed51d4327b212f23c45527f28657fe41ef045abf|53ba21e35dc87b4ef3ebda4782b06cd824c7146a6fd42342f3c6ff352c448bd8|53ba21e35dc87b4ef3ebda4782b06cd824c7146a6fd42342f3c6ff352c448bd8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Carved into a 75-metre wall of rock, the Ajanta Caves hold Buddhist monasteries and worship-halls; Caves 1, 2, 16 and 17 form the largest corpus of surviving ancient Indian wall-paintings."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the caves are carved into a 75-metre wall of rock [S1]; they hold Buddhist monasteries and worship-halls [S1]; Caves 1, 2, 16 and 17 form the largest corpus of surviving ancient Indian wall-paintings [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Ajanta Caves are Buddhist monasteries and worship-halls (cave site) in India [SUPPORTED: https://en.wikipedia.org/wiki/Ajanta_Caves]; They are carved into a 75-metre wall of rock and comprise monasteries and worship-halls [SUPPORTED: https://en.wikipedia.org/wiki/Ajanta_Caves]; Caves 1, 2, 16 and 17 form the largest corpus of surviving ancient Indian wall-paintings [SUPPORTED: https://en.wikipedia.org/wiki/Ajanta_Caves]"}]'::jsonb),
    ('ec4ea862-5a28-420c-932a-53c82693b471'::uuid, 'card_description', '850-300 BC settlement and burial site in Buyeo-gun, Chungcheongnam-do, the type-site of Middle Mumun Culture. Archaeologists use its material culture as the prehistoric Bronze Age benchmark for the.', 'Pit-houses, burials and an imposing palisade around one residential precinct: at Songguk-ri, that palisade leads archaeologists to hypothesize about conflict in local Mumun society.', 'teaser-card-s026:ec4ea862-5a28-420c-932a-53c82693b471:card_description', 'teaser-card-s026 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', 'c9fa1499011e9f6739a13f4c70e24218db61bee6d12b9226ca2070dce6c2db57|1c62acfe6ead86234f1b8c6292cf833367597b64b5c3e9eb7c09254e1263e379|1c62acfe6ead86234f1b8c6292cf833367597b64b5c3e9eb7c09254e1263e379', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pit-houses, burials and an imposing palisade around one residential precinct: at Songguk-ri, that palisade leads archaeologists to hypothesize about conflict in local Mumun society."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "pit-houses were found at Songguk-ri [S4]; Songguk-ri has burials (a burial site) [S2]; an imposing palisade stood around one residential precinct [S5]; the palisade leads archaeologists to hypothesize about conflict in local Mumun society [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-081 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Songguk-ri is a settlement and burial site (Mumun period) in South Korea [SUPPORTED: https://en.wikipedia.org/wiki/Songguk-ri]; Pit-houses were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Songguk-ri]; Burials were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Songguk-ri]; An imposing palisade surrounded one residential precinct, leading archaeologists to hypothesize about conflict in local Mumun society [SUPPORTED: https://en.wikipedia.org/wiki/Songguk-ri]"}]'::jsonb),
    ('ec838509-a1e6-4f6a-b216-3f1791c16d67'::uuid, 'card_description', 'The three supporting stones are unusually long and there are slight traces of a cairn which must have been far more extensive.', 'On the slopes of Slieve Croob, three unusually long stones hold the capstone of the Legananny Dolmen 1.8 m from the ground: a Neolithic tomb around 5,000 years old, with urns beneath.', 'teaser-card-s026:ec838509-a1e6-4f6a-b216-3f1791c16d67:card_description', 'teaser-card-s026 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'b298561ffa084055dc6c5f71e729b5ca0ccf32c1b523b186b6741a90919acc61|6efed0ebeae26567df9973e8e0ffb750a8c4c5333452144aa83a6953ad4f3e68|6efed0ebeae26567df9973e8e0ffb750a8c4c5333452144aa83a6953ad4f3e68', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the slopes of Slieve Croob, three unusually long stones hold the capstone of the Legananny Dolmen 1.8 m from the ground: a Neolithic tomb around 5,000 years old, with urns beneath."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the dolmen is on the slopes of Slieve Croob [S2]; three supporting stones hold the capstone (tripod dolmen) [S4, S7]; the three supporting stones are unusually long [S7]; the capstone is 1.8 m from the ground [S4]; it is a Neolithic tomb [S5, S6]; it is around 5,000 years old [S5]; urns were found beneath it [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Legananny Dolmen is a megalithic dolmen in Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; It lies on the slopes of Slieve Croob [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Legananny_Dolmen]; Three unusually long stones support the capstone [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; The capstone is 1.8 m from the ground [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; It is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; It is around 5,000 years old [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; It is a tomb (funerary site) [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]; Urns were found beneath it [SUPPORTED: https://en.wikipedia.org/wiki/Legananny_Dolmen]"}]'::jsonb),
    ('ed3e4264-7d20-4bbc-ba73-2d11563f2006'::uuid, 'card_description', 'Oval hillfort crowning a Lake District summit at 690 metres, where only wall foundations survive. The fort was destroyed during the Roman conquest, and the ruins were left exposed.', 'Carrock Fell, in the northern part of the Lake District national park, 8 miles north-east of Keswick, is crowned by an oval Iron Age hill fort, believed built by the Celts.', 'teaser-card-s026:ed3e4264-7d20-4bbc-ba73-2d11563f2006:card_description', 'teaser-card-s026 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '18042efcc9628ddf758b48a7408cf0c081eb1ab1b6d3be8813e03ae30cf75c14|7487b6e579653c398ae9c2df5ad050828a45fea3d3f6f11f7d02ddc9cddede09|7487b6e579653c398ae9c2df5ad050828a45fea3d3f6f11f7d02ddc9cddede09', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Carrock Fell, in the northern part of the Lake District national park, 8 miles north-east of Keswick, is crowned by an oval Iron Age hill fort, believed built by the Celts."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Carrock Fell is in the northern part of the Lake District national park [S1]; it is 8 miles north-east of Keswick [S1]; an Iron Age hill fort crowns it [S2]; the fort is oval [S4]; the fort is believed to have been built by the Celts [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Carrock Fell is a fell in the English Lake District, in the northern part of the national park [SUPPORTED: https://en.wikipedia.org/wiki/Carrock_Fell]; It lies 8 miles north-east of Keswick [SUPPORTED: https://en.wikipedia.org/wiki/Carrock_Fell]; An Iron Age hill fort crowns the summit [SUPPORTED: https://en.wikipedia.org/wiki/Carrock_Fell]; The hill fort is oval [SUPPORTED: https://en.wikipedia.org/wiki/Carrock_Fell]; The fort is believed to have been built by the Celts [SUPPORTED: https://en.wikipedia.org/wiki/Carrock_Fell]"}]'::jsonb),
    ('eef7317f-a250-434f-b34d-7933fd546da7'::uuid, 'card_description', 'The large hilltop enclosure that is Haughey''s Fort is a Scheduled Historic Monument in the townland of Tray, in Armagh City and District Council area.', 'Two concentric ditches ring the hilltop enclosure of Haughey''s Fort, 350 metres across at its widest. Occupied in the late Bronze Age, circa 1100 to 900 BC, it was then abandoned.', 'teaser-card-s026:eef7317f-a250-434f-b34d-7933fd546da7:card_description', 'teaser-card-s026 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'ee8a2a85a10ca20f29add387faeb1228b2e6de99c266aec8f0043e521b054896|d2e85a657fa08ecaa8e236e0896c521a109aafff4f4cd7d68bb058f420723b86|d2e85a657fa08ecaa8e236e0896c521a109aafff4f4cd7d68bb058f420723b86', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Two concentric ditches ring the hilltop enclosure of Haughey''s Fort, 350 metres across at its widest. Occupied in the late Bronze Age, circa 1100 to 900 BC, it was then abandoned."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "two concentric ditches surround the enclosure [S3]; Haughey''s Fort is a hilltop enclosure [S2]; the enclosure is 350 metres across at its widest [S3]; it was occupied in the late Bronze Age, circa 1100 to 900 BC [S5]; it was then abandoned [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Haughey''s Fort is a hilltop enclosure / hill fort (in Northern Ireland) [SUPPORTED: https://en.wikipedia.org/wiki/Haughey%27s_Fort]; Two concentric ditches surround the enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Haughey%27s_Fort]; It is 350 metres across at its widest [SUPPORTED: https://en.wikipedia.org/wiki/Haughey%27s_Fort]; Occupied in the late Bronze Age, circa 1100 to 900 BC [SUPPORTED: https://en.wikipedia.org/wiki/Haughey%27s_Fort]; It was then abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Haughey%27s_Fort]"}]'::jsonb),
    ('f0531983-dafb-4e80-8465-89bdc6860d27'::uuid, 'card_description', 'Around AD 65–70, Durnovaria became a civilian settlement, apparently the civitas Durotrigum of the tribal confederacy of the Durotriges.', 'Beneath the Dorset Museum lies part of the Roman road that ran through the centre of Durnovaria, a town of thermae and an aqueduct, near an earthwork the Romans made an amphitheatre.', 'teaser-card-s026:f0531983-dafb-4e80-8465-89bdc6860d27:card_description', 'teaser-card-s026 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '2f846740d6c7b895aecd6f4937605a6e0a9c96a69c72c060957383304292f9ba|382fa80a7bae3c87a0237419ad27dce38ad3a84fe6a86b0bc61ba989646ff02b|382fa80a7bae3c87a0237419ad27dce38ad3a84fe6a86b0bc61ba989646ff02b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Beneath the Dorset Museum lies part of the Roman road that ran through the centre of Durnovaria, a town of thermae and an aqueduct, near an earthwork the Romans made an amphitheatre."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "part of a Roman road lies beneath the Dorset Museum [S7]; the road ran through the centre of Durnovaria [S8]; Durnovaria was a Roman town [S1]; the town had thermae [S3]; the town had an aqueduct [S5]; the town lies near an earthwork the Romans converted into an amphitheatre [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Durnovaria was the Roman town of Dorchester (Dorset, England) [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]; Part of a Roman road lies beneath the Dorset Museum [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]; The road ran through the centre of Durnovaria [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]; The town had thermae [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]; The town had an aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]; Near the centre is an earthwork the Romans made into an amphitheatre (Maumbury Rings) [SUPPORTED: https://en.wikipedia.org/wiki/Durnovaria]"}]'::jsonb),
    ('f12e6473-3c60-4196-a99d-0611be3bb2a3'::uuid, 'card_description', 'An Iron Age sacred bog where defeated armies'' weapons and ships were offered to the gods. Items were deliberately bent, broken, or hacked apart as ritual sacrifice.', 'In the Iron Age, the weapons and ships of vanquished armies were offered to the gods at Nydam Mose. Its oak boat, dendro dated to 310–320 CE, is the only one of three still preserved.', 'teaser-card-s026:f12e6473-3c60-4196-a99d-0611be3bb2a3:card_description', 'teaser-card-s026 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '2f1bc36c1bf4937270e1ccb09eae53eaffc31d05483a20614a43e3cc89357374|0822b32bd4abd9750933f7396d9fbf387e630413b09ae21ab68ac5dfccb07903|0822b32bd4abd9750933f7396d9fbf387e630413b09ae21ab68ac5dfccb07903', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Iron Age, the weapons and ships of vanquished armies were offered to the gods at Nydam Mose. Its oak boat, dendro dated to 310–320 CE, is the only one of three still preserved."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "in the Iron Age the weapons and ships of vanquished armies were offered to the gods at Nydam Mose [S2]; an oak boat was found there [S5, S7]; the oak boat is dendro dated to 310-320 CE [S8]; three boats were found [S5, S6, S7]; the oak boat is the only one of the three still preserved [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-082 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Nydam Mose is an archaeological site (bog) in Denmark [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]; In the Iron Age the site was a sacred place where offerings were made [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]; Weapons and ships of vanquished armies were offered to the gods there [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]; The oak boat is dendro dated to 310-320 CE [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]; Three boats were found at Nydam [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]; The oak boat is the only one of the three still preserved [SUPPORTED: https://en.wikipedia.org/wiki/Nydam_Mose]"}]'::jsonb),
    ('f1c3510d-e477-440e-9755-4953f31da767'::uuid, 'card_description', 'A Neolithic dolmen whose name means "Roland''s Tomb" -- legend says his horse carried his body back from battle and buried him under this stone. The tomb predates the myth.', 'Three upright stones in an H-shape hold up a thick roofing stone at the Caixa de Rotllan, a dolmen facing south-east, listed since 1889 yet never excavated by archaeologists.', 'teaser-card-s026:f1c3510d-e477-440e-9755-4953f31da767:card_description', 'teaser-card-s026 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'c58d2fdac5b8ad05e40c448373431a356ce3110f5e57994b8d5fef75f6b40f8c|d6af6cc9ad761edd72e00701f0706b5b05d914a33feb469515503d5850a9a425|d6af6cc9ad761edd72e00701f0706b5b05d914a33feb469515503d5850a9a425', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Three upright stones in an H-shape hold up a thick roofing stone at the Caixa de Rotllan, a dolmen facing south-east, listed since 1889 yet never excavated by archaeologists."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "three upright stones in an H-shape support a thick roofing stone [S1]; the Caixa de Rotllan is a dolmen [S4]; it faces south-east (its entrance) [S2]; it has been listed since 1889 [S3]; it has never been excavated by archaeologists [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Caixa de Rotllan is a dolmen (a tomb) in France (Arles-sur-Tech, Pyrenees-Orientales) [SUPPORTED: https://en.wikipedia.org/wiki/Caixa_de_Rotllan]; It is made of three upright stones in an H-shape supporting a thick roofing stone [SUPPORTED: https://en.wikipedia.org/wiki/Caixa_de_Rotllan]; The dolmen faces south-east [SUPPORTED: https://en.wikipedia.org/wiki/Caixa_de_Rotllan]; It has been listed as a historic monument since 1889 [SUPPORTED: https://en.wikipedia.org/wiki/Caixa_de_Rotllan]; It has never been excavated by archaeologists [SUPPORTED: https://en.wikipedia.org/wiki/Caixa_de_Rotllan]"}]'::jsonb),
    ('f2046843-60ed-4081-8bbe-95cde34ec6a7'::uuid, 'card_description', 'In the late 13th century the site began to be used as a dynastic necropolis for the Marinid dynasty.', 'On the Bou Regreg estuary in Rabat, the walls of Chellah enclose a religious complex Marinid sultans built beside their mausoleums, damaged over the centuries by earthquakes and looting.', 'teaser-card-s026:f2046843-60ed-4081-8bbe-95cde34ec6a7:card_description', 'teaser-card-s026 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'b2d847fc711bb901f1cab0d56b7e1521a7addaacb713717722a8d7d25f9f3f9f|f3233e394456953894b72a4375fd6badf4ac6a282e78ecec629bbb5976c55d77|f3233e394456953894b72a4375fd6badf4ac6a282e78ecec629bbb5976c55d77', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Bou Regreg estuary in Rabat, the walls of Chellah enclose a religious complex Marinid sultans built beside their mausoleums, damaged over the centuries by earthquakes and looting."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chellah is on the Bou Regreg estuary [S1]; Chellah is in Rabat [S1]; walls at Chellah enclose a religious complex [S3]; Marinid sultans built the religious complex to accompany their mausoleums [S3]; the site was damaged over the centuries by earthquakes and looting [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Chellah is a walled necropolis/religious site in Rabat, Morocco [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; Chellah lies on the Bou Regreg estuary [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; Marinid sultans enclosed the site with walls [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; Marinid sultans built a religious complex inside the walls [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; The religious complex accompanies the sultans'' mausoleums [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; The site was damaged over the centuries by earthquakes [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]; The site was damaged over the centuries by looting [SUPPORTED: https://en.wikipedia.org/wiki/Chellah]"}]'::jsonb),
    ('f2b64b04-bcd7-4333-ac21-2641a667bef2'::uuid, 'card_description', 'An Iron Age grave field with 45 burials, a stone ship, and menhirs arranged by height—tallest to shortest. The gradient is deliberate.', 'Nine menhirs stand in a row at Stenehed, placed by height from 3.3 m to 1.4 m, beside about 45 graves, a stone circle and a stone ship of the Iron Age. Once there were eleven or twelve.', 'teaser-card-s026:f2b64b04-bcd7-4333-ac21-2641a667bef2:card_description', 'teaser-card-s026 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'c7f3172e2a6f15485c0f38c875e1b4ebd1f937e2785d01f28ad48f49d48a96f3|eda3a0df9c37bf285292323596eb4f2d46ce208047b73f250f9cc8b0de0f2cc4|eda3a0df9c37bf285292323596eb4f2d46ce208047b73f250f9cc8b0de0f2cc4', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Nine menhirs stand in a row at Stenehed, placed by height from 3.3 m to 1.4 m, beside about 45 graves, a stone circle and a stone ship of the Iron Age. Once there were eleven or twelve."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "nine menhirs stand at Stenehed today [S3]; the menhirs stand in a row [S2, S5]; they are placed according to height [S5]; they range from 3.3 m to 1.4 m [S4]; the site has about 45 graves, a stone circle and a stone ship [S2]; these belong to an Iron Age grave field [S1]; originally there were eleven or twelve menhirs [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Stenehed is an Iron Age grave field (with menhirs) in Munkedal, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The site has nine menhirs standing in a row [SUPPORTED: https://www.vgregion.se/f/kulturforvaltningen/natur-och-kulturarv/platser--landskap/underverk-i-vastra-gotaland/gravfaltet-stenehed-munkedals-kommun/]; The menhirs are placed in a row according to their heights [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The tallest menhir is 3.3 m [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The shortest menhir is 1.4 m [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The area contains about 45 graves [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The area contains a stone circle [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; The area contains a stone ship [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]; Once there were eleven or twelve menhirs [SUPPORTED: https://en.wikipedia.org/wiki/Stenehed]"}]'::jsonb),
    ('f3210979-6a62-42f6-958f-2ab8566852a8'::uuid, 'card_description', 'A 1st-century AD Roman gravity dam — a simple but massive wall of stone and concrete that held back an entire river. Roman hydraulic engineering at its most blunt.', 'Begun under Augustus, breached by flooding and rebuilt, the Roman Almonacid de la Cuba Dam on the Aguasvivas River was heightened under Trajan and is still in use today.', 'teaser-card-s026:f3210979-6a62-42f6-958f-2ab8566852a8:card_description', 'teaser-card-s026 (teaser-card): teaser card, 169 characters, checked PASS, web-verified VERIFIED', '811aaa2ec877d8dfd872c2bb1e1608772d5a3faa313079ab35b6fd444b9ed1c6|cc46b02a7a6ddb525ee7a12d90c0ed72d68582d47e285e56cabc9521da860224|cc46b02a7a6ddb525ee7a12d90c0ed72d68582d47e285e56cabc9521da860224', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Begun under Augustus, breached by flooding and rebuilt, the Roman Almonacid de la Cuba Dam on the Aguasvivas River was heightened under Trajan and is still in use today."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "construction was begun under Augustus [S2]; the dam was breached by flooding [S2]; it was rebuilt [S3]; it is a Roman dam [S1]; it is on the Aguasvivas River [S1]; it was heightened under Trajan [S4]; it is still in use today [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Almonacid de la Cuba Dam is a Roman dam in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; The dam is on the Aguasvivas River [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; Construction was begun under Augustus [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; The first dam was breached by flooding [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; It was rebuilt after the breach [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; It was heightened under Trajan [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]; It is still in use today [SUPPORTED: https://en.wikipedia.org/wiki/Almonacid_de_la_Cuba_Dam]"}]'::jsonb),
    ('f398289a-e8d6-4c38-aafb-262882827935'::uuid, 'card_description', 'Much of the road exists as an exceptionally large embankment, up to 50 ft wide and 6 ft high.', 'Up to 50 ft wide and 6 ft high, the embankment of Ackling Dyke carries a Roman road straight through prehistoric barrows, a sight that must have been meant to impress the native population.', 'teaser-card-s026:f398289a-e8d6-4c38-aafb-262882827935:card_description', 'teaser-card-s026 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '397b9f9067efc973cd2c9a80a6a8d2c77b6052d2db59562b677b8818d242c8e0|3c9a2f1fdd63a5e2d62290e9113300731bd7f4ff78a2716d933cbc3e9f6471ed|3c9a2f1fdd63a5e2d62290e9113300731bd7f4ff78a2716d933cbc3e9f6471ed', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Up to 50 ft wide and 6 ft high, the embankment of Ackling Dyke carries a Roman road straight through prehistoric barrows, a sight that must have been meant to impress the native population."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the embankment is up to 50 ft wide and 6 ft high [S2]; Ackling Dyke carries a Roman road on an embankment [S1, S2]; the road runs straight through prehistoric barrows [S6]; the embankment must have been meant to impress the native population [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-083 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Ackling Dyke is a section of Roman road in England, largely an embankment (agger) [SUPPORTED: https://en.wikipedia.org/wiki/Ackling_Dyke]; The embankment is up to 50 ft wide and 6 ft high [SUPPORTED: https://en.wikipedia.org/wiki/Ackling_Dyke]; The road cuts straight through prehistoric barrows [SUPPORTED: https://en.wikipedia.org/wiki/Ackling_Dyke]; It must have been meant to impress the native population [SUPPORTED: https://en.wikipedia.org/wiki/Ackling_Dyke]"}]'::jsonb),
    ('f46af5ba-a3d9-4d5f-9d73-0f610b666060'::uuid, 'card_description', 'Roman Teurnia was capital of the province Noricum Mediterraneum in late antiquity. It also served as a bishop''s see—where the empire ended, the church began.', 'On a wooded hill in Carinthia lie the ruins of Teurnia, a Roman city and bishop''s see, where a mosaic of the governor Ursus survives in near-perfect preservation in a basilica chapel.', 'teaser-card-s026:f46af5ba-a3d9-4d5f-9d73-0f610b666060:card_description', 'teaser-card-s026 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '6cf4233db990b5b6d998acb2841b40c336e82ed22a8fdb860ef5f532131e05c4|7f99c0fc5db813debb591e6577b69e9f716c0121a10ac1db8927fec745860a84|7f99c0fc5db813debb591e6577b69e9f716c0121a10ac1db8927fec745860a84', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a wooded hill in Carinthia lie the ruins of Teurnia, a Roman city and bishop''s see, where a mosaic of the governor Ursus survives in near-perfect preservation in a basilica chapel."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Teurnia lay on a wooded hill [S4]; its ruins lie in Carinthia [S2]; Teurnia was a Roman city [S1]; Teurnia was a bishop''s see [S3, S5]; a mosaic of the governor Ursus is there [S7]; the mosaic is in near-perfect preservation [S7]; the mosaic is in a chapel of a basilica [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Teurnia is a Roman city [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; Its ruins lie in Carinthia (Austria) [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; Teurnia was a bishop''s see [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; The site lies on a wooded hill [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; A mosaic of the governor Ursus exists at Teurnia [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; The mosaic survives in near-perfect preservation [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]; The mosaic is in a chapel of a basilica [SUPPORTED: https://en.wikipedia.org/wiki/Teurnia]"}]'::jsonb),
    ('f4864569-5406-4e10-ac59-0385cc1ad6a4'::uuid, 'card_description', 'Built in the 3rd century BC at Mieza, this Macedonian tomb features painted palmette decorations of exceptional quality — the finest surviving Hellenistic funerary painting in the region.', 'Beneath an earthen tumulus at Mieza, the Tomb of the Palmettes hides a painted old man and woman at a symposium and a ceiling of six palmettes and water lilies on a light blue background.', 'teaser-card-s026:f4864569-5406-4e10-ac59-0385cc1ad6a4:card_description', 'teaser-card-s026 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'f53d9872180a7bc8d93584247de664b70b13d6a62deee087ae1096e07e8ac60b|ce16c1f6af9ba19f3fa6a5f25c6eabb51273594332db91c7d5b2cd02937697eb|ce16c1f6af9ba19f3fa6a5f25c6eabb51273594332db91c7d5b2cd02937697eb', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Beneath an earthen tumulus at Mieza, the Tomb of the Palmettes hides a painted old man and woman at a symposium and a ceiling of six palmettes and water lilies on a light blue background."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tomb lies beneath an earthen tumulus [S3]; the tomb is at Mieza [S1]; it has a painting of an old man and woman at a symposium [S5]; its ceiling is painted with six palmettes and water lilies on a light blue background [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Tomb of the Palmettes is an ancient Macedonian tomb at Mieza [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Palmettes]; The tomb lies beneath an earthen tumulus [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Palmettes]; It has a painted old man and woman at a symposium [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Palmettes]; The ceiling has six palmettes and water lilies [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Palmettes]; The palmettes and water lilies are on a light blue background [SUPPORTED: https://en.wikipedia.org/wiki/Tomb_of_the_Palmettes]"}]'::jsonb),
    ('f4931c71-9e14-4bdc-ad9d-88bf763b6985'::uuid, 'card_description', 'El Salt is an archaeological site from the Middle Paleolithic near Alcoy which was frequented by groups of archaic humans for thousands of years.', 'Beneath a limestone wall 38 meters high, Neanderthals at El Salt left fire pits, flint tools and six teeth at least 50,000 years ago, and coprolites showing their diets included plants.', 'teaser-card-s026:f4931c71-9e14-4bdc-ad9d-88bf763b6985:card_description', 'teaser-card-s026 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '0df53b9f85469c282ad09940c9ef522420b59c3fa6fa20eb9e4ccabf9e4e2171|918e24d2d93f1823690ba1a7ffdd0fb8dc399124159bea07c8c694132dc76e39|918e24d2d93f1823690ba1a7ffdd0fb8dc399124159bea07c8c694132dc76e39', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Beneath a limestone wall 38 meters high, Neanderthals at El Salt left fire pits, flint tools and six teeth at least 50,000 years ago, and coprolites showing their diets included plants."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the site lies at the bottom of a limestone wall 38 meters high [S6]; Neanderthals left fire pits and flint tools at El Salt [S2]; six teeth were found [S2]; these date back at least 50,000 years [S2]; coprolites found at the site show Neanderthal diets included plants [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "El Salt is a Middle Paleolithic archaeological site (Neanderthal settlement site) near Alcoy, Spain [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]; The site lies at the bottom of a limestone wall 38 meters high [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]; Neanderthals left fire pits and flint tools at El Salt [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]; Six teeth were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]; The finds date to at least 50,000 years ago [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]; Coprolites were found showing the Neanderthal diet included plants [SUPPORTED: https://en.wikipedia.org/wiki/El_Salt]"}]'::jsonb),
    ('f4f9740d-f83e-4252-a014-f34c09583cf7'::uuid, 'card_description', 'Remote 5th-century BC Temple of Apollo Epicurius combining Doric, Ionic, and Corinthian columns in a single structure -- the earliest confirmed use of the Corinthian order anywhere in antiquity.', 'Cockerell and Haller came to Bassae in 1811 hoping for more successes, but all of Haller''s careful drawings of the site were lost at sea. In 1986 it was the first Greek World Heritage site.', 'teaser-card-s026:f4f9740d-f83e-4252-a014-f34c09583cf7:card_description', 'teaser-card-s026 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '0d0f093fa0f274444b9c47684211fe6d1f83025d24ac59edb2c2db8babea1760|e9b3c1842739a875ce0dc365f642a01ed000cac2d9e3ff4e6d63d0aa3ee01fff|e9b3c1842739a875ce0dc365f642a01ed000cac2d9e3ff4e6d63d0aa3ee01fff', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-028", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cockerell and Haller came to Bassae in 1811 hoping for more successes, but all of Haller''s careful drawings of the site were lost at sea. In 1986 it was the first Greek World Heritage site."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-028 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Cockerell and Haller were at Bassae in 1811 hoping for more successes [S3]; all of Haller''s careful drawings of the site were lost at sea [S3]; in 1986 Bassae was the first Greek site inscribed on the World Heritage List [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bassae is an archaeological site in Greece (site of the Temple of Apollo Epicurius) [SUPPORTED: https://en.wikipedia.org/wiki/Bassae]; Cockerell and Haller came to Bassae in 1811 [SUPPORTED: https://en.wikipedia.org/wiki/Bassae]; They hoped for more successes at Bassae [SUPPORTED: https://en.wikipedia.org/wiki/Bassae]; All of Haller''s careful drawings of the site were lost at sea [SUPPORTED: https://en.wikipedia.org/wiki/Bassae]; In 1986 Bassae became the first Greek World Heritage site [SUPPORTED: https://en.wikipedia.org/wiki/Bassae]"}]'::jsonb),
    ('f50ba7d8-09e1-4c03-8661-84d6b6d4eadd'::uuid, 'card_description', NULL, 'A rampart and ditch still enclose Yellowberries Copse: the rampart rises up to 1.8 metres, the ditch spreads up to 10 metres wide, and modern ploughing has left its scars on the earthwork.', 'teaser-card-s026:f50ba7d8-09e1-4c03-8661-84d6b6d4eadd:card_description', 'teaser-card-s026 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '63036c4a446b4462ce46da19fa2081201cdc1643aff02b1aa78909839deab499|19a3b3939771adfd2983a06a84b4e1e6717158eaaf16fbb3b006fdf5f969b7db|19a3b3939771adfd2983a06a84b4e1e6717158eaaf16fbb3b006fdf5f969b7db', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-029", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "A rampart and ditch still enclose Yellowberries Copse: the rampart rises up to 1.8 metres, the ditch spreads up to 10 metres wide, and modern ploughing has left its scars on the earthwork."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-029 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "a rampart and ditch enclose Yellowberries Copse [S2]; the rampart and ditch still survive [S3, S4]; the rampart rises up to 1.8 metres [S3]; the ditch is up to 10 metres wide [S4]; the earthwork was damaged by ploughing in the modern era [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-084 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Yellowberries Copse is an enclosure or possible hillfort (earthwork) in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Yellowberries_Copse]; A rampart and ditch enclose the site [SUPPORTED: https://en.wikipedia.org/wiki/Yellowberries_Copse]; The rampart rises up to 1.8 metres [SUPPORTED: https://en.wikipedia.org/wiki/Yellowberries_Copse]; 