    ('faf8f8ee-c092-48a8-a712-1133df65badd'::uuid, 'card_description', 'The site lies on the bank of the Lucanamarca River, west of Qaracha River, spread over three mountain tops at an altitude of 3,860 metres .', 'Spread over three mountain tops 3,860 metres up, on the bank of the Lucanamarca River in Peru''s Ayacucho Region, Pukara carries a Quechua name that means fortress.', 'teaser-card-s026:faf8f8ee-c092-48a8-a712-1133df65badd:card_description', 'teaser-card-s026 (teaser-card): teaser card, 163 characters, checked PASS, web-verified VERIFIED', '46781f7fdf9adc67c9dc2710d95ad8bd0896a584c7b94af6fc167cc863258a4e|b8895728138808f6d122ea2ce58b35a762b9349e874fb8f5921fd10402f7cd63|b8895728138808f6d122ea2ce58b35a762b9349e874fb8f5921fd10402f7cd63', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Spread over three mountain tops 3,860 metres up, on the bank of the Lucanamarca River in Peru''s Ayacucho Region, Pukara carries a Quechua name that means fortress."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pukara is spread over three mountain tops [S3]; it lies at an altitude of 3,860 metres [S3]; it is on the bank of the Lucanamarca River [S3]; it is in the Ayacucho Region of Peru [S1]; its name is Quechua and means fortress [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Pukara is a fortress-type archaeological site in the Ayacucho Region of Peru (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Pukara,_V%C3%ADctor_Fajardo]; The name Pukara is Quechua and means fortress [SUPPORTED: https://en.wikipedia.org/wiki/Pukara,_V%C3%ADctor_Faj