    ('fc215bfb-e68e-4aa0-844a-c15d8047f62f'::uuid, 'card_description', 'The Standing Stones of Stenness are a Neolithic monument five miles northeast of Stromness on the mainland of Orkney.', 'On Orkney, thin, sharp-topped slabs of the Stones of Stenness mark a Neolithic henge, possibly the oldest in the British Isles. Nearby stood the Odin Stone, pierced with a circular hole.', 'teaser-card-s026:fc215bfb-e68e-4aa0-844a-c15d8047f62f:card_description', 'teaser-card-s026 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'b94427f5d5e4be075a1a879e3e6783f7ae747f7511016afd520519da69ad24cc|8721e20852736b867324bbc675d2f2ed9daf649df243aa3e6d70eb96cf0a13a7|8721e20852736b867324bbc675d2f2ed9daf649df243aa3e6d70eb96cf0a13a7', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Orkney, thin, sharp-topped slabs of the Stones of Stenness mark a Neolithic henge, possibly the oldest in the British Isles. Nearby stood the Odin Stone, pierced with a circular hole."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Stones of Stenness are on Orkney [S1]; the stones are thin slabs [S6]; the slabs have sharp (sharply angled) tops [S6]; the monument is Neolithic [S1]; the site is a henge [S5]; it is possibly the oldest henge in the British Isles [S5]; the Odin Stone stood nearby [S7]; the Odin Stone was pierced with a circular hole [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Stones of Stenness mark a Neolithic henge on Orkney (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; The monument is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; It is a henge monument [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; The henge is possibly the oldest in the British Isles [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; The stones have sharp-topped (sharply angled) tops [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; The stones are thin slabs with sharp tops [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; An Odin Stone stood nearby, north of the henge [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]; The Odin Stone was pierced with a circular hole [SUPPORTED: https://en.wikipedia.org/wiki/Standing_Stones_of_Stenness]"}]'::jsonb),
    ('fc553d2e-73db-4bfb-b3a7-ba8f95597304'::uuid, 'card_description', 'Sandstone ridge promontory at 160 metres near Weston-under-Redcastle, enclosing about 8 hectares. Steep slopes protect all sides but the north, which received the heaviest fortification.', 'On a sandstone promontory in Shropshire, two massive ramparts close the north side of Bury Walls, an Iron Age hillfort with foundations near its centre thought to be a Romano-Celtic temple.', 'teaser-card-s026:fc553d2e-73db-4bfb-b3a7-ba8f95597304:card_description', 'teaser-card-s026 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '32471a7a604148e270cdc627683d1f8b329505ed67ad94775145441a2f0c812f|6a4602b5ebe86b742509d8d54336b528aced7c5a09e5ce3ba6e316c6dd3bf22b|6a4602b5ebe86b742509d8d54336b528aced7c5a09e5ce3ba6e316c6dd3bf22b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a sandstone promontory in Shropshire, two massive ramparts close the north side of Bury Walls, an Iron Age hillfort with foundations near its centre thought to be a Romano-Celtic temple."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bury Walls stands on a promontory of a sandstone ridge [S2]; it is in Shropshire [S1]; two massive ramparts close its north side [S4]; it is an Iron Age hillfort [S1]; foundations lie near the centre of its interior [S7]; those foundations are thought to be a Romano-Celtic temple [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Bury Walls is an Iron Age hillfort in Shropshire (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]; The site has two massive ramparts [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]; It lies on a promontory of a sandstone ridge [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]; Two massive ramparts close the north side [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]; Foundations near the centre are thought to be a Romano-Celtic temple [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]; The foundations are more recently thought to be the remains of a Romano-Celtic temple [SUPPORTED: https://en.wikipedia.org/wiki/Bury_Walls]"}]'::jsonb),
    ('fc8f7864-e56c-4e21-a4c1-57c18e31d358'::uuid, 'card_description', 'A two-story Roman villa rustica from the 1st century AD whose tower-like stone skeleton still stands — its purpose debated for centuries, theories ranging from villa to watchtower.', 'On the Mount of Santo Antão rises the Tower of Centum Cellas, 12 m high and among the best preserved Roman monuments in Portugal. Of the extensions around it, only foundations are visible.', 'teaser-card-s026:fc8f7864-e56c-4e21-a4c1-57c18e31d358:card_description', 'teaser-card-s026 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '578b5f7829420b9eaaf6739046d12e36d535092ce5cd8bd9effa3e484f82f719|46888b13d8a23286ad2e554f7e51792c9e11fec6c20e49ff0034996b4517e3e8|46888b13d8a23286ad2e554f7e51792c9e11fec6c20e49ff0034996b4517e3e8', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Mount of Santo Antão rises the Tower of Centum Cellas, 12 m high and among the best preserved Roman monuments in Portugal. Of the extensions around it, only foundations are visible."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the tower stands on the Mount of Santo Antão [S1]; the tower is 12 m high [S5]; it is among the best preserved Roman monuments in Portugal [S2]; it was surrounded by extensions [S6]; only the foundations of those extensions are visible [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Centum Cellas is a tower-like Roman structure (villa rustica) on the Mount of Santo Antão, Portugal (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Cellas]; Centum Cellas is a Roman monument [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Cellas]; The tower is 12 m high [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Cellas]; It is among the best preserved Roman monuments in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Cellas]; It was surrounded on three sides by extensions of which only the foundations are visible [SUPPORTED: https://en.wikipedia.org/wiki/Centum_Cellas]"}]'::jsonb),
    ('fd42ae8f-5d57-4764-9d0e-5020eaf3eb13'::uuid, 'card_description', 'Caves and stone buildings on a forested Rhone valley hill, inhabited continuously from the Neolithic until the early 20th century. A chapel from 1706, partly built in a cave, still stands.', 'Above the Rhône valley, the caves and stone buildings of the Barry Troglodyte Village were inhabited from the neolithic to the early 20th century, their chapel of 1706 partly set in a cave.', 'teaser-card-s026:fd42ae8f-5d57-4764-9d0e-5020eaf3eb13:card_description', 'teaser-card-s026 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'b1b548f165ecc788d76404a05ccf05d950c68d976b792951b1e2d26ab7bc0cbc|b1d98bdd50cd2ff58be30c02b919852680aca3c5ddd7b54bfbcebf02825fd47e|b1d98bdd50cd2ff58be30c02b919852680aca3c5ddd7b54bfbcebf02825fd47e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Above the Rhône valley, the caves and stone buildings of the Barry Troglodyte Village were inhabited from the neolithic to the early 20th century, their chapel of 1706 partly set in a cave."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the village overlooks the Rhône valley [S2]; it consists of caves and stone buildings [S3]; it was inhabited from the neolithic to the early 20th century [S3]; it has a chapel of 1706 [S4]; the chapel is partly built in a cave [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-088 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Barry Troglodyte Village is an archaeological site of caves and stone buildings above the Rhone valley, France (central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Barry_Troglodyte_Village]; It lies on a hill overlooking the Rhone valley [SUPPORTED: https://en.wikipedia.org/wiki/Barry_Troglodyte_Village]; It comprises caves and stone buildings [SUPPORTED: https://en.wikipedia.org/wiki/Barry_Troglodyte_Village]; It was inhabited from the neolithic until the early 20th century [SUPPORTED: https://en.wikipedia.org/wiki/Barry_Troglodyte_Village]; A chapel from 1706 is partly built in a cave [SUPPORTED: https://en.wikipedia.org/wiki/Barry_Troglodyte_Village]"}]'::jsonb),
    ('fd7b2e9e-b11e-4d94-83b4-c94b03f323d1'::uuid, 'card_description', 'Covering 8 hectares on Stockbridge Down, this univallate fort has a single bank rising 2.7 meters. Ploughing erased the eastern defenses, leaving the western rampart sharply defined.', 'On Stockbridge Down lies Woolbury, an Iron Age hilltop camp of 20 acres. Its single bank and ditch are well preserved to the west, where the entrance leads into an interior of pasture.', 'teaser-card-s026:fd7b2e9e-b11e-4d94-83b4-c94b03f323d1:card_description', 'teaser-card-s026 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '22976fb7850ff1325a06da4db8016cf8a35058b44cb8ce7fbb74aaae05cac2a2|aaaa36f00d87dd86a4ae30897cc6562ba0430cfc91c860673610772708bf2f40|aaaa36f00d87dd86a4ae30897cc6562ba0430cfc91c860673610772708bf2f40', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On Stockbridge Down lies Woolbury, an Iron Age hilltop camp of 20 acres. Its single bank and ditch are well preserved to the west, where the entrance leads into an interior of pasture."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Woolbury lies on Stockbridge Down [S1]; it is Iron Age [S1]; it is a hilltop camp [S2]; it covers 20 acres [S2]; it has a single bank and ditch [S2]; the bank and ditch are well preserved to the west [S3]; the entrance is on the western side [S5]; the interior is pasture [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Woolbury lies on Stockbridge Down [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; Woolbury is a hillfort (hilltop camp) [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; It dates to the Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; It is a hilltop camp [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; It covers 20 acres [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; It has a single bank and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; Bank and ditch are well preserved to the west [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; The entrance is in the west [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]; The interior is pasture [SUPPORTED: https://en.wikipedia.org/wiki/Woolbury]"}]'::jsonb),
    ('fe268a4c-2d51-42f9-a00e-addd8fe217da'::uuid, 'card_description', 'The Longstone is a megalithic monument near the village of Mottistone close to the south west coast of the Isle of Wight.', 'The only megalithic monument on the Isle of Wight, the Longstone stands 3.9 metres high with a smaller stone at its foot, perhaps the entrance to a long barrow, probably Neolithic.', 'teaser-card-s026:fe268a4c-2d51-42f9-a00e-addd8fe217da:card_description', 'teaser-card-s026 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'a7db4c3532fd9b0e757d5908c6067403688ab90bccc0eadec34d8a8b435c8709|848af340e7e9597644d37acbdcff95aa1c4fbc36e9203b1e6b37d8125c4f8a5b|848af340e7e9597644d37acbdcff95aa1c4fbc36e9203b1e6b37d8125c4f8a5b', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The only megalithic monument on the Isle of Wight, the Longstone stands 3.9 metres high with a smaller stone at its foot, perhaps the entrance to a long barrow, probably Neolithic."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Longstone is the only megalithic monument on the Isle of Wight [S1, S2]; the (larger) stone stands 3.9 metres high [S4]; a smaller stone lies at its foot [S4]; the stones are perhaps the entrance of a long barrow [S6]; the monument is probably Neolithic [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Longstone is a megalithic monument at Mottistone, Isle of Wight [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstone,_Mottistone]; It is the only megalithic monument on the Isle of Wight [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstone,_Mottistone]; The larger stone stands 3.9 metres high, with a smaller stone at its foot [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstone,_Mottistone]; The stones may be the entrance to a long barrow [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstone,_Mottistone]; It is probably Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/The_Longstone,_Mottistone]"}]'::jsonb),
    ('feccbb16-9c3a-4d0e-9aac-ca8cf3d370d8'::uuid, 'card_description', 'The Via Egnatia was constructed in order to link a chain of Roman colonies stretching from the Adriatic Sea to the Bosphorus.', 'From the Adriatic to the Bosphorus, the Via Egnatia joined a chain of Roman colonies, its terminus almost opposite that of the Via Appia, giving the southern Balkans a direct link to Rome.', 'teaser-card-s026:feccbb16-9c3a-4d0e-9aac-ca8cf3d370d8:card_description', 'teaser-card-s026 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '91bc9856833d0793378b1ed6cc9e350ccd6ccd50d147ea9ebf50da5a846bb24e|137795b555885f2b24b2da3336430f139639ead0156addfd8584b4cd9e52831e|137795b555885f2b24b2da3336430f139639ead0156addfd8584b4cd9e52831e', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "From the Adriatic to the Bosphorus, the Via Egnatia joined a chain of Roman colonies, its terminus almost opposite that of the Via Appia, giving the southern Balkans a direct link to Rome."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Via Egnatia linked a chain of Roman colonies [S1]; that chain stretched from the Adriatic to the Bosphorus [S1]; its terminus lay almost opposite the terminus of the Via Appia [S2]; it gave the (colonies of the) southern Balkans a direct connection to Rome [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "The Via Egnatia is a Roman road passing through North Macedonia [SUPPORTED: https://en.wikipedia.org/wiki/Via_Egnatia]; It ran from the Adriatic to the Bosphorus joining a chain of Roman colonies [SUPPORTED: https://en.wikipedia.org/wiki/Via_Egnatia]; Its terminus was almost opposite that of the Via Appia [SUPPORTED: https://en.wikipedia.org/wiki/Via_Egnatia]; It gave the southern Balkans a direct link to Rome [SUPPORTED: https://en.wikipedia.org/wiki/Via_Egnatia]"}]'::jsonb),
    ('ff3a9a41-c6ee-459a-ad30-cced049e2dbb'::uuid, 'card_description', 'A major Roman city on the Danube whose name comes from the Thracian word for "water." Ongoing excavations keep revealing new parts of this once-thriving settlement.', 'On the Danube near Gigen, the walled city of Oescus, once a Roman legionary fortress, traces an irregular pentagon. Here in 1948 the mosaic known as The Achaeans came to light.', 'teaser-card-s026:ff3a9a41-c6ee-459a-ad30-cced049e2dbb:card_description', 'teaser-card-s026 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '336cb0a0818ebf24bf257833b2e9698fac4d1628cad9b1ac703129617f9d72d3|ad2f17b8c533f2727cbc1e71e1fce10ffecac1016a645be06b45116e6b535d22|ad2f17b8c533f2727cbc1e71e1fce10ffecac1016a645be06b45116e6b535d22', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Danube near Gigen, the walled city of Oescus, once a Roman legionary fortress, traces an irregular pentagon. Here in 1948 the mosaic known as The Achaeans came to light."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Oescus lies on the Danube [S1]; it lies near Gigen [S3]; it is a walled city [S7]; it was once a Roman legionary fortress [S4, S5]; the walled city has the shape of an irregular pentagon [S7]; the mosaic known as The Achaeans was discovered there in 1948 [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Oescus was an ancient city on the Danube [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; It lies near Gigen [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; Oescus was a walled city [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; It was once a Roman legionary fortress [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; The walled city traces an irregular pentagon [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; The mosaic known as The Achaeans was found in 1948 [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]; The Achaeans is a mosaic [SUPPORTED: https://en.wikipedia.org/wiki/Oescus]"}]'::jsonb),
    ('ff687661-ccd0-484c-9fe7-c966649818c0'::uuid, 'card_description', 'A Gallo-Roman settlement at the foot of Lake Zurich and precursor of modern Zurich. It sat on the border between two Roman provinces and served as a tax-collection point.', 'On the Lindenhof hill of Zurich lay the heart of Turicum, a Gallo-Roman town of public baths, graves and jewelry, its name first recorded on a 2nd-century tombstone found in 1747.', 'teaser-card-s026:ff687661-ccd0-484c-9fe7-c966649818c0:card_description', 'teaser-card-s026 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'c1b4812d626c51c54e3085282b6449558de9cd3668eeca6cdbbd93d8e1370650|6dd60be180fb683567b6faf152d288533dcfc5dd3f67580625ccf650f4127128|6dd60be180fb683567b6faf152d288533dcfc5dd3f67580625ccf650f4127128', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On the Lindenhof hill of Zurich lay the heart of Turicum, a Gallo-Roman town of public baths, graves and jewelry, its name first recorded on a 2nd-century tombstone found in 1747."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the core of Turicum was the Lindenhof hill in Zurich [S2]; Turicum was a Gallo-Roman settlement/town [S1, S3]; remains of public baths were excavated [S6]; graves were excavated [S6]; jewelry was excavated [S6]; the town''s name is first recorded on a 2nd-century tombstone [S3]; that tombstone was found in 1747 [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-089 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Turicum was a Gallo-Roman town [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; The heart of Turicum lay on the Lindenhof hill of Zurich [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; Public baths were excavated [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; Graves were excavated [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; Jewelry was found [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; The earliest record of the name is on a tombstone [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; The tombstone is of the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]; The tombstone was found in 1747 [SUPPORTED: https://en.wikipedia.org/wiki/Turicum]"}]'::jsonb),
    ('ff70aa7e-7371-4ffd-b673-175fd0c56ab4'::uuid, 'card_description', 'A dolmen with three orthostats capped by a large slab at 1,020 meters altitude. At 3000 BC, Neolithic people hauled megaliths to mountaintop burial sites.', 'In the Sierra de Guara, the Dolmen Losa de la Mora rests a large slab on three orthostats, from around 3000 BC. Excavators found stone axes, flint tools and the bones of several people.', 'teaser-card-s026:ff70aa7e-7371-4ffd-b673-175fd0c56ab4:card_description', 'teaser-card-s026 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '8fa2878a7ec5797b8e7fb4a027ed8d1ebd5012b99d6c0161dff008ca863af3a2|964d4d8a1b5d44c6a17263362f36f1ef3af02f395d55041a85322b83ec8cc52f|964d4d8a1b5d44c6a17263362f36f1ef3af02f395d55041a85322b83ec8cc52f', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "In the Sierra de Guara, the Dolmen Losa de la Mora rests a large slab on three orthostats, from around 3000 BC. Excavators found stone axes, flint tools and the bones of several people."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the dolmen is in the Sierra de Guara [S1]; a large slab rests on three orthostats [S4]; it dates from around 3000 BC [S3]; excavators found stone axes [S6]; excavators found flint tools [S6]; excavators found skeletal remains of several individuals [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Dolmen Losa de la Mora is a dolmen (tomb) in the Sierra de Guara, Spain [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; It dates from around 3000 BC [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; It has a large slab [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; The slab rests on three orthostats [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; Excavators found stone axes [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; Excavators found flint tools [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; Excavators found the bones of several people [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]; The site was excavated [SUPPORTED: https://es.wikipedia.org/wiki/Dolmen_de_la_Losa_Mora]"}]'::jsonb),
    ('ffe651cf-023d-48fe-a0e2-7f6d73281d7f'::uuid, 'card_description', 'An Iron Age enclosure that may not have been defensive at all. Stock control and religious functions have been attributed to its three overlapping enclosures.', 'Within the Iron Age hillfort of Casterley Camp lie three apparently related enclosures, linked to stock control and religion, and on its west side runs a trackway between earth banks.', 'teaser-card-s026:ffe651cf-023d-48fe-a0e2-7f6d73281d7f:card_description', 'teaser-card-s026 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'e811da0581aca815d3e65e9d0dd6ac9e91e5852c5d77b21bd0d56ac31864b801|ddfabe47d4d29ddfdca4c217a06258cf0f152d28f7d27a32f4197fd528d02818|ddfabe47d4d29ddfdca4c217a06258cf0f152d28f7d27a32f4197fd528d02818', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Within the Iron Age hillfort of Casterley Camp lie three apparently related enclosures, linked to stock control and religion, and on its west side runs a trackway between earth banks."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Casterley Camp is an Iron Age hillfort [S1]; three apparently related enclosures lie within the site [S4]; stock control and religious functions are attributed to the enclosures [S5]; a trackway runs on the west side of the site [S6]; the trackway has earth banks on both sides [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Casterley Camp is an Iron Age hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; Casterley Camp is in England (Wiltshire) [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; Within it lie three enclosures [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; The three enclosures are apparently related [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; The enclosures are linked to stock control [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; The enclosures are linked to religion [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; A trackway runs on its west side [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]; The trackway has earth banks on both sides [SUPPORTED: https://en.wikipedia.org/wiki/Casterley_Camp]"}]'::jsonb),
    ('fff0e7ae-45b8-49c3-8ce4-8bf72cf03d04'::uuid, 'card_description', 'Sitting at just 67 meters on Bloxworth Heath, this Late Bronze Age to Early Iron Age fort is unusual for lowland heath — despite its modest elevation it dominates the flat surrounding landscape.', 'On a flat-topped knoll of Bloxworth Heath, between the rivers Sherford and Piddle, a single rampart encloses Woolsbarrow Hillfort, dating from the Late Bronze Age to the Early Iron Age.', 'teaser-card-s026:fff0e7ae-45b8-49c3-8ce4-8bf72cf03d04:card_description', 'teaser-card-s026 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '43faf2e31019b5189885fe00be72b581fda773e35bf2c8ed603ca6d1abb7ea28|d1a00727c246bfce19c73bbc4af56c25ab4ac97c6beffa226be817e87de701f6|d1a00727c246bfce19c73bbc4af56c25ab4ac97c6beffa226be817e87de701f6', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a flat-topped knoll of Bloxworth Heath, between the rivers Sherford and Piddle, a single rampart encloses Woolsbarrow Hillfort, dating from the Late Bronze Age to the Early Iron Age."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the hillfort is on a flat-topped knoll [S3]; the knoll is on Bloxworth Heath [S1, S3]; it lies between the rivers Sherford and Piddle [S3]; a single rampart encloses the hillfort [S3, S4]; it dates from the Late Bronze Age to the Early Iron Age [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Woolsbarrow is a hillfort (England, Bloxworth Heath) [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; It stands on a flat-topped knoll on Bloxworth Heath between the rivers Sherford and Piddle [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; It is in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; A single rampart encloses it [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; It dates from the Late Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; It dates to the Early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]; It dates from the Late Bronze Age to the Early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Woolsbarrow_Hillfort]"}]'::jsonb),
    ('fffb6208-b675-47ff-8a0b-4d11f455b0ff'::uuid, 'card_description', 'The Five Marys is a group of Bronze Age round barrows near the village of Chaldon Herring, in Dorset.', 'On a ridge above Chaldon Herring lie the Five Marys, Bronze Age barrows. In two of them, deep chalk-cut graves held men in a sitting position, stag antlers laid over each shoulder.', 'teaser-card-s026:fffb6208-b675-47ff-8a0b-4d11f455b0ff:card_description', 'teaser-card-s026 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'da108153d70cbf572decce9928b05d1efc9e89b04fddaca5f8b730460d03ea4f|f1a121f1b5b1f21284a386e34a0f2c50f6779b48e2bb596bafa4ea4e3845b4ed|f1a121f1b5b1f21284a386e34a0f2c50f6779b48e2bb596bafa4ea4e3845b4ed', '[{"source": "lane WB run wb-ws-2026-09-27-05: writer teaser-wb-ws-2026-09-27-05-write-030", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "On a ridge above Chaldon Herring lie the Five Marys, Bronze Age barrows. In two of them, deep chalk-cut graves held men in a sitting position, stag antlers laid over each shoulder."}, {"source": "lane WB run wb-ws-2026-09-27-05: checker teaser-wb-ws-2026-09-27-05-check-030 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "the Five Marys lie on a ridge above Chaldon Herring [S2]; they are Bronze Age barrows [S1]; two of the barrows held deep chalk-cut graves [S6, S7]; the graves held men (male skeletons) [S7]; the men were in a sitting position [S7]; stag antlers lay over each shoulder [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-05: verifier teaser-wb-ws-2026-09-27-05-verify-090 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-05/OUTCOMES.jsonl", "quote": "Five Marys are Bronze Age barrows (a group of round barrows) in Dorset [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; They lie on a ridge above Chaldon Herring [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; Two of the barrows were excavated and contained graves [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; The graves were deep and cut into chalk [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; In two of them, graves held men in a sitting position [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; They are in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]; Stag antlers were laid over each shoulder [SUPPORTED: https://en.wikipedia.org/wiki/Five_Marys]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 50;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s026', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s026'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s026'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 50 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s026'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
